<style>
  #home, #countdown { box-sizing: border-box; scroll-margin-top: 72px; font-family: var(--j2-font-body, 'Inter', system-ui, sans-serif); }
  #home *, #countdown * { box-sizing: border-box; }

  #home.j2-hero {
    position: relative;
    overflow: hidden;
    background: var(--j2-secondary, #0B1F3A);
    color: #FFFFFF;
    padding: 56px 16px 64px;
  }
  #home.j2-hero::before {
    content: "";
    position: absolute;
    top: 0; right: -20%; bottom: 0;
    width: 55%;
    background: var(--j2-primary, #0B3D91);
    transform: skewX(-18deg);
    opacity: 0.55;
    pointer-events: none;
  }
  #home.j2-hero::after {
    content: "";
    position: absolute;
    left: 0; right: 0; bottom: 0;
    height: 8px;
    background: var(--j2-accent, #FF5A1F);
    pointer-events: none;
  }
  #home .w1-wrap { position: relative; z-index: 1; max-width: 1080px; margin: 0 auto; }
  #home .w1-kicker {
    margin: 0 0 8px;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    font-size: 0.875rem;
    color: #FFB59A;
  }
  #home h1 {
    margin: 0 0 16px;
    font-family: var(--j2-font-heading, 'Barlow Condensed', Impact, sans-serif);
    font-weight: 800;
    text-transform: uppercase;
    line-height: 0.95;
    letter-spacing: 0.01em;
    font-size: clamp(2.75rem, 13vw, 6.5rem);
    overflow-wrap: break-word;
  }
  #home .w1-lead { margin: 0 0 24px; font-size: clamp(1rem, 3.6vw, 1.25rem); max-width: 40ch; color: #E6ECF5; }
  #home .w1-facts { display: grid; grid-template-columns: 1fr; gap: 12px; margin: 0 0 32px; padding: 0; max-width: 900px; }
  #home .w1-facts > div { border-left: 6px solid var(--j2-accent, #FF5A1F); padding: 4px 0 4px 14px; min-width: 0; }
  #home .w1-facts dt { font-size: 0.8125rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: #FFB59A; }
  #home .w1-facts dd { margin: 2px 0 0; font-size: clamp(1.05rem, 4vw, 1.375rem); font-weight: 600; overflow-wrap: break-word; }
  #home .j2-hero-cta { max-width: 100%; text-align: center; }

  #countdown {
    background: var(--j2-bg, #F5F7FA);
    color: var(--j2-text, #0B1F3A);
    padding: 48px 16px;
    text-align: center;
  }
  #countdown .w1-wrap { max-width: 760px; margin: 0 auto; }
  #countdown h2 {
    margin: 0 0 8px;
    font-family: var(--j2-font-heading, 'Barlow Condensed', Impact, sans-serif);
    font-weight: 800;
    text-transform: uppercase;
    font-size: clamp(1.75rem, 7vw, 2.75rem);
    line-height: 1;
  }
  #countdown .w1-note { margin: 0 0 24px; color: var(--j2-muted, #4A5568); font-size: 1.0625rem; }
  #countdown-timer { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
  #countdown .w1-unit {
    min-width: 0;
    background: var(--j2-surface, #FFFFFF);
    color: var(--j2-text, #0B1F3A);
    border: 2px solid var(--j2-secondary, #0B1F3A);
    border-radius: var(--j2-radius, 12px);
    box-shadow: 4px 4px 0 var(--j2-primary, #0B3D91);
    padding: 12px 4px;
  }
  #countdown .w1-num {
    display: block;
    font-family: var(--j2-font-heading, 'Barlow Condensed', Impact, sans-serif);
    font-weight: 800;
    font-size: clamp(1.875rem, 9vw, 3.5rem);
    line-height: 1;
    font-variant-numeric: tabular-nums;
  }
  #countdown .w1-label { display: block; margin-top: 4px; font-size: 0.75rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--j2-muted, #4A5568); }
  #countdown .w1-msg { margin: 16px 0 0; font-weight: 700; min-height: 1.5em; }

  @media (min-width: 720px) {
    #home.j2-hero { padding: 96px 32px 104px; }
    #home .w1-facts { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    #countdown { padding: 72px 32px; }
    #countdown-timer { gap: 16px; }
    #countdown .w1-unit { padding: 20px 8px; }
    #countdown .w1-label { font-size: 0.875rem; }
  }

  body.hc-mode #home.j2-hero { background: #000000; color: #FFFFFF; }
  body.hc-mode #home.j2-hero::before { background: #000000; opacity: 1; }
  body.hc-mode #home.j2-hero::after { background: #FFEB3B; }
  body.hc-mode #home .w1-kicker, body.hc-mode #home .w1-facts dt { color: #FFEB3B; }
  body.hc-mode #home .w1-lead { color: #FFFFFF; }
  body.hc-mode #home .w1-facts > div { border-left-color: #FFEB3B; }
