<script>
(function () {
  try {
    var raceEl = document.getElementById('fee-race');
    var runnersEl = document.getElementById('fee-runners');
    var shirtsEl = document.getElementById('fee-shirts');
    var totalEl = document.getElementById('fee-total');
    if (!raceEl || !runnersEl || !shirtsEl || !totalEl) { return; }

    var SHIRT_PRICE = 250;
    // Early-bird runs to the end of 31 December 2026, India Standard Time (UTC+05:30)
    var EARLY_END = new Date('2026-12-31T23:59:59.999+05:30').getTime();

    function money(n) { return 'Rs ' + n.toLocaleString('en-IN'); }
    function text(id, value) { var el = document.getElementById(id); if (el) { el.textContent = value; } }

    function update() {
      var fee = parseInt(raceEl.value, 10);
      var opt = raceEl.options[raceEl.selectedIndex];
      var raceName = opt ? opt.getAttribute('data-name') : 'Race';
      var runners = Number(runnersEl.value);
      var shirts = Number(shirtsEl.value);
      var status = '';

      var runnersOk = runnersEl.value !== '' && isFinite(runners) && Math.floor(runners) === runners && runners >= 1 && runners <= 10;
      var shirtsOk = shirtsEl.value !== '' && isFinite(shirts) && Math.floor(shirts) === shirts && shirts >= 0;

      if (!runnersOk || !shirtsOk || isNaN(fee)) {
        totalEl.textContent = 'Rs 0';
        text('fee-line-race', 'Rs 0');
        text('fee-line-discount', 'Rs 0');
        text('fee-line-shirts', 'Rs 0');
        text('fee-status', !runnersOk ? 'Enter a whole number of runners from 1 to 10.' : 'Enter a whole number of T-shirts, 0 or more.');
        return;
      }

      var early = Date.now() <= EARLY_END;
      var raceTotal = fee * runners;
      var discount = early ? (raceTotal * 10) / 100 : 0;
      var shirtTotal = shirts * SHIRT_PRICE;
      var total = raceTotal - discount + shirtTotal;

      text('fee-line-race-label', 'Race fees (' + runners + ' x ' + raceName + ' at ' + money(fee) + ')');
      text('fee-line-race', money(raceTotal));
      text('fee-line-discount', discount > 0 ? '-' + money(discount) : 'Rs 0');
      text('fee-line-shirts-label', 'T-shirts (' + shirts + ' x ' + money(SHIRT_PRICE) + ')');
      text('fee-line-shirts', money(shirtTotal));
      totalEl.textContent = money(total);
      status = early
        ? 'Early-bird applied: 10% off race fees only.'
        : 'Early-bird ended on 31 December 2026. Full race fees apply.';
      text('fee-status', status);
    }

    ['input', 'change', 'keyup'].forEach(function (evt) {
      raceEl.addEventListener(evt, update);
      runnersEl.addEventListener(evt, update);
      shirtsEl.addEventListener(evt, update);
    });
    update();
  } catch (e) {
    /* calculator keeps its default text if anything goes wrong */
  }
})();
</script>
