(function () {
  try {
    var form = document.getElementById('fee-form');
    var race = document.getElementById('fee-race');
    var runners = document.getElementById('fee-runners');
    var shirts = document.getElementById('fee-shirts');
    var total = document.getElementById('fee-total');
    if (!form || !race || !runners || !shirts || !total) { return; }

    var raceSum = document.getElementById('fee-race-sum');
    var discountEl = document.getElementById('fee-discount');
    var shirtSum = document.getElementById('fee-shirt-sum');
    var errorEl = document.getElementById('fee-error');
    var statusEl = document.getElementById('fee-status');

    var SHIRT_PRICE = 250;
    // Early-bird runs to the end of 31 December 2026, India Standard Time (UTC+05:30)
