    function money(n) { return 'Rs ' + n.toLocaleString('en-IN'); }
    function text(el, value) { if (el) { el.textContent = value; } }

    function update() {
      var early = Date.now() < EARLY_BIRD_END;
      text(statusEl, early
        ? 'Early-bird discount applies to your registration today.'
        : 'The early-bird period ended on 31 December 2026, so no discount applies.');

      var fee = parseInt(race.value, 10) || 0;
      var n = parseInt(runners.value, 10);
      var s = parseInt(shirts.value, 10);
      var problems = [];

      if (isNaN(n) || n < 1 || n > 10) {
        problems.push('Enter 1 to 10 runners.');
        n = isNaN(n) ? 1 : Math.min(10, Math.max(1, n));
      }
      if (isNaN(s) || s < 0) {
        problems.push('Enter 0 or more T-shirts.');
        s = isNaN(s) ? 0 : Math.max(0, s);
