      text(errorEl, problems.length ? problems.join(' ') + ' Total shown uses ' + n + ' runner' + (n === 1 ? '' : 's') + ' and ' + s + ' T-shirt' + (s === 1 ? '' : 's') + '.' : '');

      var raceFees = fee * n;
      var discount = early ? Math.round(raceFees * 0.1) : 0;
      var shirtFees = s * SHIRT_PRICE;
      var sum = raceFees - discount + shirtFees;

      text(raceSum, money(raceFees));
      text(discountEl, discount > 0 ? '- ' + money(discount) : money(0));
      text(shirtSum, money(shirtFees));
      text(total, money(sum));
    }

    form.addEventListener('submit', function (e) { e.preventDefault(); update(); });
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    update();
  } catch (err) {
    /* calculator keeps its default text if anything goes wrong */
  }
})();
