(function () {
  try {
    var root = document.getElementById('faq');
    if (!root) { return; }
    var buttons = root.querySelectorAll('.faq-q');

    function bind(btn) {
      var panel = document.getElementById(btn.getAttribute('aria-controls'));
      if (!panel) { return; }
      // Answers start collapsed once the script runs; without JS they stay visible.
      panel.hidden = true;
      btn.setAttribute('aria-expanded', 'false');
      btn.addEventListener('click', function () {
        var open = btn.getAttribute('aria-expanded') === 'true';
        btn.setAttribute('aria-expanded', open ? 'false' : 'true');
        panel.hidden = open;
      });
    }

    for (var i = 0; i < buttons.length; i++) { bind(buttons[i]); }
  } catch (err) {
    /* answers stay visible if the script fails */
  }
})();
</script>
