    <li><a class="nav-link" href="#contact">Contact</a></li>
  </ul>
</nav>

<script>
(function () {
  try {
    var nav = document.getElementById('site-nav');
    if (!nav) { return; }
    var links = nav.querySelectorAll('.nav-link');
    var byId = {};
    var order = [];
    for (var i = 0; i < links.length; i++) {
      var id = (links[i].getAttribute('href') || '').replace('#', '');
      if (id) { byId[id] = links[i]; order.push(id); }
    }
    // The countdown sits under the hero, so it counts as Home.
    var alias = { countdown: 'home' };
    var watched = order.concat(['countdown']);
    var current = null;

    function setActive(id) {
      id = alias[id] || id;
      if (!id || id === current || !byId[id]) { return; }
      current = id;
      for (var j = 0; j < links.length; j++) {
        var on = links[j] === byId[id];
        links[j].classList.toggle('is-active', on);
        if (on) { links[j].setAttribute('aria-current', 'true'); } else { links[j].removeAttribute('aria-current'); }
      }
      // Keep the active link visible inside the menu without scrolling the page.
      var link = byId[id];
      var target = link.offsetLeft - (nav.clientWidth - link.offsetWidth) / 2;
      nav.scrollLeft = Math.max(0, target);
    }

    function atBottom() {
      return window.innerHeight + window.pageYOffset >= document.documentElement.scrollHeight - 4;
    }

    // Fallback: the last section whose top has passed the middle of the screen.
    function fromScroll() {
      if (atBottom()) { setActive(order[order.length - 1]); return; }
      var line = window.innerHeight * 0.4;
      var found = order[0];
      for (var k = 0; k < watched.length; k++) {
        var el = document.getElementById(watched[k]);
        if (el && el.getBoundingClientRect().top <= line) { found = watched[k]; }
      }
      setActive(found);
    }

    if ('IntersectionObserver' in window) {
      var seen = {};
      var io = new IntersectionObserver(function (entries) {
        for (var m = 0; m < entries.length; m++) { seen[entries[m].target.id] = entries[m].isIntersecting; }
        if (atBottom()) { setActive(order[order.length - 1]); return; }
        var pick = null;
        for (var n = 0; n < watched.length; n++) { if (seen[watched[n]]) { pick = watched[n]; } }
        if (pick) { setActive(pick); }
      }, { rootMargin: '-60px 0px -50% 0px', threshold: 0 });
      for (var w = 0; w < watched.length; w++) {
        var sec = document.getElementById(watched[w]);
        if (sec) { io.observe(sec); }
      }
      window.addEventListener('scroll', function () { if (atBottom()) { setActive(order[order.length - 1]); } }, { passive: true });
    } else {
      window.addEventListener('scroll', fromScroll, { passive: true });
    }

    window.addEventListener('resize', fromScroll);
    fromScroll();
  } catch (err) {
    /* menu still works as plain anchor links if the script fails */
  }
})();
</script>
