<script>
(function () {
  try {
    var timer = document.getElementById('countdown-timer');
    if (!timer) { return; }
    var msg = document.getElementById('countdown-msg');
    // Start of race day, 14 February 2027, India Standard Time (UTC+05:30)
    var target = new Date('2027-02-14T00:00:00+05:30').getTime();
    var nodes = {
      days: timer.querySelector('[data-unit="days"]'),
      hours: timer.querySelector('[data-unit="hours"]'),
      minutes: timer.querySelector('[data-unit="minutes"]'),
      seconds: timer.querySelector('[data-unit="seconds"]')
    };
    var intervalId = null;

    function pad(n) { return (n < 10 ? '0' : '') + n; }
    function set(key, value) { if (nodes[key]) { nodes[key].textContent = value; } }

    function tick() {
      var diff = target - Date.now();
      if (isNaN(diff) || diff <= 0) {
        set('days', '00'); set('hours', '00'); set('minutes', '00'); set('seconds', '00');
        if (msg) { msg.textContent = 'Race day has arrived.'; }
        if (intervalId !== null) { clearInterval(intervalId); intervalId = null; }
        return;
      }
      var totalSeconds = Math.floor(diff / 1000);
      var days = Math.floor(totalSeconds / 86400);
      var hours = Math.floor((totalSeconds % 86400) / 3600);
      var minutes = Math.floor((totalSeconds % 3600) / 60);
      var seconds = totalSeconds % 60;
      set('days', days < 100 ? pad(days) : String(days));
      set('hours', pad(hours));
      set('minutes', pad(minutes));
      set('seconds', pad(seconds));
    }

    tick();
    intervalId = setInterval(tick, 1000);
  } catch (e) {
    /* countdown stays at its default text if anything goes wrong */
  }
})();
</script>
