<script>
(function () {
  try {
    var wrap = document.getElementById('contrast-wrap');
    var btn = document.getElementById('contrast-toggle');
    var stateEl = document.getElementById('contrast-state');
    var live = document.getElementById('contrast-live');
    if (!wrap || !btn || !document.body) { return; }
    var KEY = 'riverside-run-contrast';

    // Move the bar to the top of the page content, under the fixed menu, in normal flow.
    // If the hero is missing, the bar stays where it is and still overlaps nothing.
    var home = document.getElementById('home');
    if (home && home.parentNode) { home.parentNode.insertBefore(wrap, home); }

    function apply(on, announce) {
      document.body.classList.toggle('hc-mode', on);
      btn.setAttribute('aria-pressed', on ? 'true' : 'false');
      if (stateEl) { stateEl.textContent = on ? 'On' : 'Off'; }
      if (announce && live) { live.textContent = on ? 'High contrast mode on' : 'High contrast mode off'; }
    }

    function stored() {
      try { return window.localStorage.getItem(KEY); } catch (e) { return null; }
    }
    function save(on) {
      try { window.localStorage.setItem(KEY, on ? '1' : '0'); } catch (e) { /* choice just won't be remembered */ }
