(function () {
  try {
    var nav = document.getElementById('site-nav');
    if (!nav) { return; }
    var links = nav.querySelectorAll('.nav-link');
    var byId = {};
    var order = [];
    for (var i = 0; i < links.length; i++) {
      var id = (links[i].getAttribute('href') || '').replace('#', '');
      if (id) { byId[id] = links[i]; order.push(id); }
    }
    // The countdown sits inside the hero, so it counts as Home.
    var alias = { countdown: 'home' };

    // Watch sections in the order they appear on the page, not menu order,
    // so the highlight stays right wherever a section sits.
    var watched = [];
    var all = order.concat(['countdown']);
    for (var a = 0; a < all.length; a++) {
      if (document.getElementById(all[a])) { watched.push(all[a]); }
    }
    watched.sort(function (x, y) {
      var ex = document.getElementById(x);
      var ey = document.getElementById(y);
      if (ex === ey) { return 0; }
      return (ex.compareDocumentPosition(ey) & 4) ? -1 : 1;
    });
    var first = watched[0] || order[0];
    var last = watched[watched.length - 1] || order[order.length - 1];
    var current = null;

    function setActive(id) {
      id = alias[id] || id;
      if (!id || id === current || !byId[id]) { return; }
      current = id;
      for (var j = 0; j < links.length; j++) {
        var on = links[j] === byId[id];
        links[j].classList.toggle('is-active', on);
        if (on) { links[j].setAttribute('aria-current', 'true'); } else { links[j].removeAttribute('aria-current'); }
      }
