      var link = byId[id];
      var target = link.offsetLeft - (nav.clientWidth - link.offsetWidth) / 2;
      nav.scrollLeft = Math.max(0, target);
    }

    function atBottom() {
      return window.innerHeight + window.pageYOffset >= document.documentElement.scrollHeight - 4;
    }

    // Fallback: the last section whose top has passed 40% of the screen height.
    function fromScroll() {
      if (atBottom()) { setActive(last); return; }
      var line = window.innerHeight * 0.4;
      var found = first;
      for (var k = 0; k < watched.length; k++) {
        var el = document.getElementById(watched[k]);
        if (el && el.getBoundingClientRect().top <= line) { found = watched[k]; }
      }
      setActive(found);
    }

    if ('IntersectionObserver' in window) {
      var seen = {};
      var io = new IntersectionObserver(function (entries) {
        for (var m = 0; m < entries.length; m++) { seen[entries[m].target.id] = entries[m].isIntersecting; }
        if (atBottom()) { setActive(last); return; }
        var pick = null;
        for (var n = 0; n < watched.length; n++) { if (seen[watched[n]]) { pick = watched[n]; } }
        if (pick) { setActive(pick); }
      }, { rootMargin: '-60px 0px -50% 0px', threshold: 0 });
      for (var w = 0; w < watched.length; w++) {
        var sec = document.getElementById(watched[w]);
        if (sec) { io.observe(sec); }
      }
      window.addEventListener('scroll', function () { if (atBottom()) { setActive(last); } }, { passive: true });
    } else {
      window.addEventListener('scroll', fromScroll, { passive: true });
    }

    window.addEventListener('resize', fromScroll);
    fromScroll();
  } catch (err) {
    /* menu still works as plain anchor links if the script fails */
  }
})();
