(function () {
  try {
    var form = document.getElementById('register-form');
    var tshirt = document.getElementById('reg-tshirt');
    var wrap = document.getElementById('tshirt-size-wrap');
    var size = document.getElementById('reg-tshirt-size');
    var dob = document.getElementById('reg-dob');
    var guardian = document.getElementById('guardian-name');
    var guardianLabel = document.getElementById('guardian-label');
    var statusEl = document.getElementById('register-status');
    if (!form || !tshirt || !wrap || !size || !dob || !guardian) { return; }

    function pad(n) { return (n < 10 ? '0' : '') + n; }

    // Date of birth cannot be in the future
    var now = new Date();
    dob.setAttribute('max', now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate()));

    function updateShirt() {
      var yes = tshirt.value === 'Yes';
      wrap.hidden = !yes;
      size.disabled = !yes;
      size.required = yes;
      if (!yes) { size.selectedIndex = 0; }
    }

    function isUnder18() {
      var parts = (dob.value || '').split('-');
      if (parts.length !== 3) { return false; }
      var y = parseInt(parts[0], 10), m = parseInt(parts[1], 10), d = parseInt(parts[2], 10);
      if (isNaN(y) || isNaN(m) || isNaN(d)) { return false; }
      var eighteenth = new Date(y + 18, m - 1, d);
      return eighteenth.getTime() > Date.now();
    }

    function updateGuardian() {
      var under = isUnder18();
      guardian.required = under;
      guardian.setAttribute('aria-required', under ? 'true' : 'false');
      if (guardianLabel) {
        guardianLabel.textContent = under ? 'Guardian name (required)' : 'Guardian name (only if under 18)';
      }
    }

    tshirt.addEventListener('change', updateShirt);
    dob.addEventListener('input', updateGuardian);
    dob.addEventListener('change', updateGuardian);

    form.addEventListener('submit', function () {
      if (statusEl) {
        statusEl.textContent = 'Your email app should open with your registration. Send that email to finish. If nothing opens, email run@example.com.';
      }
    });

    updateShirt();
    updateGuardian();
  } catch (err) {
    /* form still works as a plain mailto form if the script fails */
  }
})();
</script>
