<section id="fees" aria-labelledby="fees-title">
  <div class="w4-wrap">
    <h2 id="fees-title">Fee calculator</h2>
    <p class="w4-intro">Pick your race, the number of runners and the number of T-shirts to see what you will pay.</p>
    <div class="j2-card w4-card">
      <div class="fee-calc" role="group" aria-labelledby="fees-title">
        <div class="w4-fields">
          <div class="w4-field">
            <label for="fee-race">Race</label>
            <select id="fee-race" name="race">
              <option value="" selected>Choose a race</option>
              <option value="300">5K (Rs 300)</option>
              <option value="500">10K (Rs 500)</option>
              <option value="800">Half Marathon (Rs 800)</option>
            </select>
          </div>
          <div class="w4-field">
            <label for="fee-runners">Runners</label>
            <input id="fee-runners" name="runners" type="number" inputmode="numeric" min="1" max="10" step="1" value="1">
            <p class="w4-hint">1 to 10 runners</p>
          </div>
          <div class="w4-field">
            <label for="fee-shirts">T-shirts</label>
            <input id="fee-shirts" name="shirts" type="number" inputmode="numeric" min="0" step="1" placeholder="Optional">
            <p class="w4-hint">Rs 250 each, optional</p>
          </div>
        </div>

        <div class="w4-rules">
          <p>Early-bird: 10% off race fees only, not T-shirts, for registrations up to 31 December 2026.</p>
          <p id="fee-status"></p>
        </div>

        <p class="w4-error" id="fee-error" role="alert"></p>

        <dl class="w4-breakdown" id="fee-breakdown" aria-label="Fee breakdown" hidden>
          <div><dt>Race fees</dt><dd id="fee-race-sum"></dd></div>
          <div><dt>Early-bird discount</dt><dd id="fee-discount"></dd></div>
          <div><dt>T-shirts</dt><dd id="fee-shirt-sum"></dd></div>
        </dl>
        <div class="w4-totalrow">
          <span class="w4-totallabel">Total to pay</span>
          <output id="fee-total" class="is-prompt" for="fee-race fee-runners fee-shirts" aria-live="polite">Choose a race to see your total</output>
        </div>
      </div>
    </div>
  </div>
</section>

<script>
(function () {
  try {
    var box = document.querySelector('#fees .fee-calc');
    var race = document.getElementById('fee-race');
    var runners = document.getElementById('fee-runners');
    var shirts = document.getElementById('fee-shirts');
    var total = document.getElementById('fee-total');
    if (!box || !race || !runners || !shirts || !total) { return; }

    var breakdown = document.getElementById('fee-breakdown');
    var raceSum = document.getElementById('fee-race-sum');
    var discountEl = document.getElementById('fee-discount');
    var shirtSum = document.getElementById('fee-shirt-sum');
    var errorEl = document.getElementById('fee-error');
    var statusEl = document.getElementById('fee-status');

    var SHIRT_PRICE = 250;
    var PROMPT = 'Choose a race to see your total';
    // Early-bird runs to the end of 31 December 2026, India Standard Time (UTC+05:30)
    var EARLY_BIRD_END = new Date('2027-01-01T00:00:00+05:30').getTime();

    function money(n) { return 'Rs ' + n.toLocaleString('en-IN'); }
    function text(el, value) { if (el) { el.textContent = value; } }

    function showPrompt() {
      text(total, PROMPT);
      total.classList.add('is-prompt');
      if (breakdown) { breakdown.hidden = true; }
      text(raceSum, '');
      text(discountEl, '');
      text(shirtSum, '');
    }

    function update() {
      var early = Date.now() < EARLY_BIRD_END;
      text(statusEl, early
        ? 'Early-bird discount applies to your registration today.'
        : 'The early-bird period ended on 31 December 2026, so no discount applies.');

      var chosen = String(race.value) !== '';
      var fee = chosen ? (parseInt(race.value, 10) || 0) : 0;
      var n = parseInt(runners.value, 10);
      var blankShirts = String(shirts.value).trim() === '';
      var s = blankShirts ? 0 : parseInt(shirts.value, 10);
      var problems = [];

      if (isNaN(n) || n < 1 || n > 10) {
        problems.push('Enter 1 to 10 runners.');
        n = isNaN(n) ? 1 : Math.min(10, Math.max(1, n));
      }
      if (isNaN(s) || s < 0) {
        problems.push('T-shirts cannot be negative.');
        s = isNaN(s) ? 0 : Math.max(0, s);
      }

      if (!chosen) {
        text(errorEl, problems.join(' '));
        showPrompt();
        return;
      }

      text(errorEl, problems.length
        ? problems.join(' ') + ' Total shown uses ' + n + ' runner' + (n === 1 ? '' : 's') + (s > 0 ? ' and ' + s + ' T-shirt' + (s === 1 ? '' : 's') : ' and no T-shirts') + '.'
        : '');

      var raceFees = fee * n;
      var discount = early ? Math.round(raceFees * 0.1) : 0;
      var shirtFees = s * SHIRT_PRICE;
      var sum = raceFees - discount + shirtFees;

      text(raceSum, money(raceFees));
      text(discountEl, discount > 0 ? '- ' + money(discount) : 'None');
      text(shirtSum, shirtFees > 0 ? money(shirtFees) : 'None');
      if (breakdown) { breakdown.hidden = false; }
      total.classList.remove('is-prompt');
      text(total, money(sum));
    }

    box.addEventListener('input', update);
    box.addEventListener('change', update);
    update();
  } catch (err) {
    /* calculator keeps its prompt text if anything goes wrong */
  }
})();
</script>
